"use client";

import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { cn } from "@/lib/utils";
import { useDirection } from "./hooks/use-direction";
import {
  createCountText,
  createDateFormatters,
  resolveLocale,
} from "./lib/format-default";
import { ChipRow } from "./parts/chip-row";
import { DateRangePicker } from "./parts/date-range-picker";
import { SearchInput } from "./parts/search-input";
import {
  DEFAULT_LABELS,
  type DateRange,
  type FilterBarCategoryItem,
  type FilterBarProps,
  type FilterBarValue,
} from "./types";

const ALIGN_CLASSES = {
  left: "items-start text-start",
  center: "items-center text-center",
  right: "items-end text-end",
} as const;

const ALIGN_JUSTIFY = {
  left: "justify-start",
  center: "justify-center",
  right: "justify-end",
} as const;

const normalizeCategories = (
  input: FilterBarCategoryItem[] | string[] | undefined,
): FilterBarCategoryItem[] => {
  if (!input) return [];
  return input.map((entry) =>
    typeof entry === "string" ? { value: entry, label: entry } : entry,
  );
};

/**
 * FilterBar — composite filter bar with search + category chips + date-range
 * + optional results count. Each sub-control is independently controlled-or-
 * uncontrolled; a combined `onChange` fires once per user interaction (never
 * from an effect, so not on mount unless `emitInitialChange`).
 */
function FilterBarImpl(props: FilterBarProps) {
  const {
    categories,
    search: controlledSearch,
    defaultSearch = "",
    onSearchChange,
    searchDebounceMs = 250,
    debounceControlledSearch = false,
    searchAccessory,
    category: controlledCategory,
    defaultCategory = null,
    onCategoryChange,
    dateRange: controlledDateRange,
    defaultDateRange = { from: undefined, to: undefined },
    onDateRangeChange,
    onChange,
    emitInitialChange = false,
    resultsCount,
    align = "center",
    hideSearch = false,
    hideCategories = false,
    hideDateRange = false,
    labels: labelsProp,
    formatDateRange: formatDateRangeProp,
    formatDate: formatDateProp,
    locale: localeProp,
    timeZone,
    calendarLocale,
    dir: dirProp,
    className,
  } = props;

  const rootRef = useRef<HTMLDivElement>(null);
  const dir = useDirection(rootRef, dirProp);

  // ─── Locale-aware defaults (built here, memoised — never module scope) ───
  const locale = useMemo(() => resolveLocale(localeProp), [localeProp]);
  const dateFormatters = useMemo(
    () => createDateFormatters(locale, timeZone),
    [locale, timeZone],
  );
  const formatDateRange = formatDateRangeProp ?? dateFormatters.formatDateRange;
  const formatDate = formatDateProp ?? dateFormatters.formatDate;
  const localePassed = localeProp !== undefined;
  const defaultCountText = useMemo(
    () => createCountText(localePassed ? locale : undefined),
    [localePassed, locale],
  );

  const labels = useMemo(() => {
    // An `undefined` value never erases a default (dropped before merging, for every key);
    // the default count text follows `locale`.
    const defined = Object.fromEntries(
      Object.entries(labelsProp ?? {}).filter(([, v]) => v !== undefined),
    );
    const merged = { ...DEFAULT_LABELS, ...defined };
    if (!labelsProp?.resultsCountText) merged.resultsCountText = defaultCountText;
    return merged;
  }, [labelsProp, defaultCountText]);

  const normalizedCategories = useMemo(
    () => normalizeCategories(categories),
    [categories],
  );

  // ─── Search state ────────────────────────────────────────
  const [internalSearch, setInternalSearch] = useState(defaultSearch);
  const isSearchControlled = controlledSearch !== undefined;
  const search = isSearchControlled ? controlledSearch : internalSearch;

  // ─── Category state ──────────────────────────────────────
  const [internalCategory, setInternalCategory] = useState<string | null>(
    defaultCategory,
  );
  const isCategoryControlled = controlledCategory !== undefined;
  const category = isCategoryControlled ? controlledCategory : internalCategory;

  // ─── Date range state ────────────────────────────────────
  const [internalDateRange, setInternalDateRange] = useState<DateRange>(defaultDateRange);
  const isDateRangeControlled = controlledDateRange !== undefined;
  const dateRange = isDateRangeControlled ? controlledDateRange : internalDateRange;

  // ─── Combined onChange ───────────────────────────────────
  // Emitted from the user handlers only, with the merged next value. The latest
  // render's values live in a ref so the handlers stay stable.
  const latest = useRef({ search, category, dateRange, onChange });
  useEffect(() => {
    latest.current = { search, category, dateRange, onChange };
  });

  const emit = useCallback((patch: Partial<FilterBarValue>) => {
    const cur = latest.current;
    cur.onChange?.({
      search: cur.search,
      category: cur.category,
      dateRange: cur.dateRange,
      ...patch,
    });
  }, []);

  const applySearch = useCallback(
    (next: string) => {
      if (!isSearchControlled) setInternalSearch(next);
      onSearchChange?.(next);
    },
    [isSearchControlled, onSearchChange],
  );

  const handleSearchChange = useCallback(
    (next: string) => {
      applySearch(next);
      emit({ search: next });
    },
    [applySearch, emit],
  );

  // Another control was used while a search commit was pending: commit the visible text
  // first so this interaction's single `onChange` carries it (and no late search-only
  // `onChange` follows). Returns the flushed text as a patch, or `{}`.
  const searchFlushRef = useRef<(() => string | undefined) | null>(null);
  const flushSearch = useCallback((): Partial<FilterBarValue> => {
    const pending = searchFlushRef.current?.();
    if (pending === undefined) return {};
    applySearch(pending);
    return { search: pending };
  }, [applySearch]);

  const handleCategoryChange = useCallback(
    (next: string | null) => {
      const flushed = flushSearch();
      if (!isCategoryControlled) setInternalCategory(next);
      onCategoryChange?.(next);
      emit({ ...flushed, category: next });
    },
    [isCategoryControlled, onCategoryChange, emit, flushSearch],
  );

  const handleDateRangeChange = useCallback(
    (next: DateRange) => {
      const flushed = flushSearch();
      if (!isDateRangeControlled) setInternalDateRange(next);
      onDateRangeChange?.(next);
      emit({ ...flushed, dateRange: next });
    },
    [isDateRangeControlled, onDateRangeChange, emit, flushSearch],
  );

  // Opt-in single emission on mount (a ref guards the StrictMode effect replay).
  const initialEmitted = useRef(false);
  useEffect(() => {
    if (!emitInitialChange || initialEmitted.current) return;
    initialEmitted.current = true;
    emit({});
  }, [emitInitialChange, emit]);

  const filtersRowVisible = !hideCategories || !hideDateRange;
  const justify = ALIGN_JUSTIFY[align];

  return (
    <div
      ref={rootRef}
      className={cn(
        "flex flex-col gap-6",
        ALIGN_CLASSES[align],
        className,
      )}
    >
      {!hideSearch ? (
        <SearchInput
          value={search}
          onChange={handleSearchChange}
          debounced={!isSearchControlled || debounceControlledSearch}
          debounceMs={searchDebounceMs}
          placeholder={labels.searchPlaceholder}
          ariaLabel={labels.searchAriaLabel}
          accessory={searchAccessory}
          flushRef={searchFlushRef}
          className="w-full max-w-xl"
        />
      ) : null}

      {filtersRowVisible ? (
        <div className={cn("flex flex-wrap items-center gap-4", justify)}>
          {!hideCategories && normalizedCategories.length > 0 ? (
            <ChipRow
              items={normalizedCategories}
              value={category}
              onChange={handleCategoryChange}
              allLabel={labels.allLabel}
              ariaLabel={labels.categoriesAriaLabel}
              className={justify}
            />
          ) : null}
          {!hideDateRange ? (
            <DateRangePicker
              value={dateRange}
              onChange={handleDateRangeChange}
              buttonText={labels.dateButtonText}
              clearLabel={labels.clearDateLabel}
              clearText={labels.clearDateText}
              loadErrorText={labels.calendarLoadErrorText}
              retryText={labels.calendarRetryText}
              timeZone={timeZone}
              formatRange={formatDateRange}
              formatDate={formatDate}
              calendarLocale={calendarLocale}
              dir={dir}
            />
          ) : null}
        </div>
      ) : null}

      {/* Always mounted so the first announcement is not lost to a late-inserted region. */}
      <p aria-live="polite" className="text-sm text-muted-foreground empty:hidden">
        {resultsCount !== undefined ? labels.resultsCountText(resultsCount) : null}
      </p>
    </div>
  );
}

export const FilterBar = memo(FilterBarImpl);
FilterBar.displayName = "FilterBar";

export default FilterBar;

// Re-export the value type for consumers importing from the root file.
export type { FilterBarValue };

export { FilterBar, default } from "./filter-bar";
export type {
  DateRange,
  FilterBarAlign,
  FilterBarCategoryItem,
  FilterBarLabels,
  FilterBarProps,
  FilterBarValue,
} from "./types";

// @ilinxa/filter-bar 0.3.0

import { createCountText } from "./lib/format-default";
import type { ReactNode } from "react";
import type { Locale } from "react-day-picker";

export interface DateRange {
  from?: Date;
  to?: Date;
}

export interface FilterBarValue {
  search: string;
  category: string | null;
  dateRange: DateRange;
}

export interface FilterBarCategoryItem {
  value: string;
  label?: string;
}

export interface FilterBarLabels {
  /** Search placeholder. Default: 'Search…'. */
  searchPlaceholder?: string;
  /** Search input aria-label. Default: 'Search'. */
  searchAriaLabel?: string;
  /** "All" chip label. Default: 'All'. */
  allLabel?: string;
  /** Date trigger label when no range set. Default: 'Filter by date'. */
  dateButtonText?: string;
  /** Aria-label on the clear-date button. Default: 'Clear date filter'. */
  clearDateLabel?: string;
  /** Visible text on the clear-date button. Default: 'Clear date'. */
  clearDateText?: string;
  /** Results count formatter. Default: "1 item found" / "{n} items found" (English plural rules). */
  resultsCountText?: (count: number) => string;
  /** ARIA group label for the chip row. Default: 'Filter by category'. */
  categoriesAriaLabel?: string;
  /** Shown when the lazily loaded calendar fails to load. Default: "Couldn't load the calendar.". */
  calendarLoadErrorText?: string;
  /** Retry button text beside the load-error message. Default: 'Try again'. */
  calendarRetryText?: string;
}

export type FilterBarAlign = "left" | "center" | "right";

export interface FilterBarProps {
  /** Categories to render in the chip row. Pass `string[]` as shorthand. */
  categories?: FilterBarCategoryItem[] | string[];

  // ─── Search (controlled-or-uncontrolled) ──────────────
  search?: string;
  defaultSearch?: string;
  onSearchChange?: (search: string) => void;
  /** Debounce in ms for uncontrolled mode (and controlled mode with `debounceControlledSearch`). Default: 250. */
  searchDebounceMs?: number;
  /**
   * Controlled `search` only. Off (default): `onSearchChange` fires on every keystroke.
   * On: the input keeps a local echo and commits after `searchDebounceMs`. The prop wins whenever
   * it changes to a value that is not one of your own commits (URL change, reset): the field
   * resyncs to it. While a commit is pending the field shows the user's typing, and a host that
   * never adopts a commit leaves the field showing the typed text until the prop next changes.
   */
  debounceControlledSearch?: boolean;
  /** Trailing slot inside the search field (after the input in tab order). */
  searchAccessory?: ReactNode;

  // ─── Category (controlled-or-uncontrolled) ────────────
  category?: string | null;
  defaultCategory?: string | null;
  onCategoryChange?: (category: string | null) => void;

  // ─── Date range (controlled-or-uncontrolled) ──────────
  dateRange?: DateRange;
  defaultDateRange?: DateRange;
  onDateRangeChange?: (range: DateRange) => void;

  // ─── Combined emitter ─────────────────────────────────
  /**
   * Fires from user interactions only, once each, with the merged next value. Not on mount,
   * not when this callback's identity changes, not when a controlled prop changes from outside.
   */
  onChange?: (value: FilterBarValue) => void;
  /** Fire `onChange` once on mount with the initial value. Default: false. */
  emitInitialChange?: boolean;

  // ─── Display ──────────────────────────────────────────
  resultsCount?: number;
  align?: FilterBarAlign;
  hideSearch?: boolean;
  hideCategories?: boolean;
  hideDateRange?: boolean;

  // ─── i18n + theming ───────────────────────────────────
  labels?: FilterBarLabels;
  formatDateRange?: (range: { from: Date; to: Date }) => string;
  formatDate?: (date: Date) => string;
  /** BCP 47 tag for the default date + count formatting. Default `"en"`; an invalid tag falls back to `"en"`. */
  locale?: string;
  /** IANA time zone for the default date formatting and the calendar's day math. Default: the runtime's zone. */
  timeZone?: string;
  /** A react-day-picker / date-fns `Locale` object (host imports it) for the calendar's month and day names. */
  calendarLocale?: Locale;
  /** Text direction for the calendar popover. Default: resolved from the nearest `[dir]`. */
  dir?: "ltr" | "rtl";

  // ─── Overrides ────────────────────────────────────────
  className?: string;
}

export const DEFAULT_LABELS: Required<FilterBarLabels> = {
  searchPlaceholder: "Search…",
  searchAriaLabel: "Search",
  allLabel: "All",
  dateButtonText: "Filter by date",
  clearDateLabel: "Clear date filter",
  clearDateText: "Clear date",
  resultsCountText: (count) => createCountText(undefined)(count),
  categoriesAriaLabel: "Filter by category",
  calendarLoadErrorText: "Couldn't load the calendar.",
  calendarRetryText: "Try again",
};

/**
 * Default date + count formatters, built from `Intl` for an explicit locale / time zone
 * (consumer contract C3). Created inside the component and memoised on `locale` /
 * `timeZone` — never at module scope, never with an `undefined` locale.
 */

/** Locale used when none is passed, or when the tag is invalid. */
export const DEFAULT_LOCALE = "en";

/** The tag if `Intl` accepts it and supports it, else `"en"`. */
export function resolveLocale(locale: string | undefined): string {
  if (!locale) return DEFAULT_LOCALE;
  try {
    const tag = Intl.getCanonicalLocales(locale)[0];
    // A well-formed tag the runtime has no data for would silently use the runtime's own
    // locale (server/client mismatch), so only supported tags are kept.
    if (!tag || Intl.DateTimeFormat.supportedLocalesOf([tag]).length === 0) return DEFAULT_LOCALE;
    return tag;
  } catch {
    return DEFAULT_LOCALE;
  }
}

/** A time zone `Intl` accepts, else `undefined` (the runtime's zone). */
function resolveTimeZone(timeZone: string | undefined): string | undefined {
  if (!timeZone) return undefined;
  try {
    new Intl.DateTimeFormat(DEFAULT_LOCALE, { timeZone });
    return timeZone;
  } catch {
    return undefined;
  }
}

export function createDateFormatters(locale: string, timeZone?: string) {
  const tz = resolveTimeZone(timeZone);
  const short = new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "short",
    timeZone: tz,
  });
  const long = new Intl.DateTimeFormat(locale, {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: tz,
  });
  return {
    formatDate: (date: Date): string => long.format(date),
    formatDateRange: ({ from, to }: { from: Date; to: Date }): string =>
      `${short.format(from)} - ${short.format(to)}`,
  };
}

/**
 * Default count text: "1 item found" / "{n} items found". Plural selection uses English
 * rules because the text is English; override `labels.resultsCountText` to translate.
 * The number is grouped with `Intl.NumberFormat` only when the host passed a `locale`.
 */
export function createCountText(formatLocale: string | undefined) {
  const plural = new Intl.PluralRules(DEFAULT_LOCALE);
  const numberFormat = formatLocale ? new Intl.NumberFormat(formatLocale) : null;
  return (count: number): string => {
    const shown = numberFormat ? numberFormat.format(count) : String(count);
    return plural.select(count) === "one" ? `${shown} item found` : `${shown} items found`;
  };
}

"use client";

import { useEffect, useRef, useState, type ReactNode, type RefObject } from "react";
import { Search } from "lucide-react";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

/** Commits awaiting an echo are capped, so a host that never adopts them cannot grow the list. */
const MAX_UNECHOED = 10;

/**
 * Search input with magnifier icon.
 *
 * `debounced` (uncontrolled mode, or controlled with `debounceControlledSearch`): the input
 * keeps a local echo and commits to `onChange` after `debounceMs`. When the controlled
 * `value` later differs from the last commit (URL change, reset), the echo resyncs to it.
 * Otherwise the prop is the source of truth and every keystroke calls `onChange`.
 *
 * Commits the host has not yet echoed back are tracked in order: a prop value equal to one of
 * them is an echo (it and every earlier entry are dropped), never an external change.
 *
 * `flushRef` is internal: the parent calls it when another control is used while a commit
 * is pending. It commits the pending text (no `onChange`) and returns it, so the parent can
 * fold it into the one combined emission for that interaction.
 */
export function SearchInput({
  value,
  onChange,
  debounced,
  debounceMs,
  placeholder,
  ariaLabel,
  accessory,
  className,
  flushRef,
}: {
  value: string;
  onChange: (next: string) => void;
  debounced: boolean;
  debounceMs: number;
  placeholder: string;
  ariaLabel: string;
  accessory?: ReactNode;
  className?: string;
  flushRef?: RefObject<(() => string | undefined) | null>;
}) {
  const [localValue, setLocalValue] = useState(value);
  const [committed, setCommitted] = useState(value);
  const [seenValue, setSeenValue] = useState(value);
  // Commits not yet echoed back by the host, oldest first.
  const [unechoed, setUnechoed] = useState<string[]>([]);

  // Structural resync: the prop moved. An echo of one of our commits is not external.
  if (value !== seenValue) {
    setSeenValue(value);
    const at = unechoed.indexOf(value);
    if (at >= 0) {
      setUnechoed(unechoed.slice(at + 1));
    } else {
      setUnechoed([]);
      setCommitted(value);
      setLocalValue(value);
    }
  }

  const live = useRef({ localValue, committed, debounced });
  useEffect(() => {
    live.current = { localValue, committed, debounced };
  });

  useEffect(() => {
    if (!flushRef) return;
    flushRef.current = () => {
      const cur = live.current;
      if (!cur.debounced || cur.localValue === cur.committed) return undefined;
      live.current = { ...cur, committed: cur.localValue };
      setCommitted(cur.localValue);
      setUnechoed((list) => [...list, cur.localValue].slice(-MAX_UNECHOED));
      return cur.localValue;
    };
    return () => {
      flushRef.current = null;
    };
  }, [flushRef]);

  // Latest callback without restarting the debounce timer when its identity changes.
  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  });

  useEffect(() => {
    if (!debounced) return;
    if (localValue === committed) return;
    const id = setTimeout(() => {
      setCommitted(localValue);
      setUnechoed((list) => [...list, localValue].slice(-MAX_UNECHOED));
      onChangeRef.current(localValue);
    }, debounceMs);
    return () => clearTimeout(id);
  }, [localValue, committed, debounced, debounceMs]);

  const hasAccessory = accessory !== undefined && accessory !== null && accessory !== false;

  return (
    <div role="search" className={cn("relative", className)}>
      <Search
        aria-hidden="true"
        className="absolute start-4 top-1/2 h-5 w-5 -translate-y-1/2 text-muted-foreground"
      />
      <Input
        type="search"
        value={debounced ? localValue : value}
        onChange={(event) => {
          const next = event.target.value;
          if (debounced) setLocalValue(next);
          else onChange(next);
        }}
        placeholder={placeholder}
        aria-label={ariaLabel}
        className={cn(
          "h-14 rounded-xl border-border/50 ps-12 text-lg focus-visible:border-primary",
          hasAccessory && "pe-14",
        )}
      />
      {hasAccessory ? (
        <div className="absolute end-3 top-1/2 flex -translate-y-1/2 items-center">
          {accessory}
        </div>
      ) : null}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { FilterBarCategoryItem } from "../types";

/**
 * Pill-row of category chips. The first chip is the "All" sentinel —
 * clicking it sets value to null (clears the category filter).
 *
 * Active chip uses Button `variant="default"` (filled lime), inactive uses
 * `variant="outline"`. Each chip is a real button with `aria-pressed`.
 */
export function ChipRow({
  items,
  value,
  onChange,
  allLabel,
  ariaLabel,
  className,
}: {
  items: FilterBarCategoryItem[];
  value: string | null;
  onChange: (value: string | null) => void;
  allLabel: string;
  ariaLabel: string;
  className?: string;
}) {
  return (
    <div
      role="group"
      aria-label={ariaLabel}
      className={cn("flex flex-wrap gap-2", className)}
    >
      <Button
        variant={value === null ? "default" : "outline"}
        size="sm"
        aria-pressed={value === null}
        onClick={() => onChange(null)}
        className="rounded-full"
      >
        {allLabel}
      </Button>
      {items.map((item) => (
        <Button
          key={item.value}
          variant={value === item.value ? "default" : "outline"}
          size="sm"
          aria-pressed={value === item.value}
          onClick={() => onChange(item.value)}
          className="rounded-full"
        >
          {item.label ?? item.value}
        </Button>
      ))}
    </div>
  );
}

"use client";

import { lazy, Suspense, useState } from "react";
import { Calendar as CalendarIcon, ChevronDown, X } from "lucide-react";
import type { Locale } from "react-day-picker";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import type { DateRange } from "../types";
import { CalendarErrorBoundary } from "./calendar-error-boundary";

// The calendar (react-day-picker + date-fns) loads only when the popover first opens.
const loadCalendar = () =>
  lazy(() =>
    import("./date-range-calendar").then((m) => ({ default: m.DateRangeCalendar })),
  );

function CalendarSkeleton() {
  return (
    <div aria-hidden="true" className="flex gap-4 p-3">
      <div className="h-64 w-56 animate-pulse rounded-md bg-muted motion-reduce:animate-none" />
      <div className="hidden h-64 w-56 animate-pulse rounded-md bg-muted motion-reduce:animate-none md:block" />
    </div>
  );
}

/**
 * Date-range Popover. Renders a 2-month calendar in range mode.
 * Conditional clear-X button appears next to the trigger when a range is set.
 *
 * Composes shadcn Popover + a lazily loaded Calendar (react-day-picker; date-fns is a
 * transitive peer).
 */
export function DateRangePicker({
  value,
  onChange,
  buttonText,
  clearLabel,
  clearText,
  formatRange,
  formatDate,
  calendarLocale,
  timeZone,
  loadErrorText,
  retryText,
  dir,
}: {
  value: DateRange;
  onChange: (next: DateRange) => void;
  buttonText: string;
  clearLabel: string;
  clearText: string;
  formatRange: (range: { from: Date; to: Date }) => string;
  formatDate: (date: Date) => string;
  calendarLocale?: Locale;
  timeZone?: string;
  loadErrorText: string;
  retryText: string;
  dir: "ltr" | "rtl";
}) {
  // `lazy` caches a failed chunk load, so Retry builds a fresh lazy component.
  const [DateRangeCalendar, setDateRangeCalendar] = useState(loadCalendar);
  const hasRange = value.from !== undefined || value.to !== undefined;

  let triggerText = buttonText;
  if (value.from && value.to) {
    triggerText = formatRange({ from: value.from, to: value.to });
  } else if (value.from) {
    triggerText = formatDate(value.from);
  }

  return (
    <div className="flex items-center gap-2">
      <Popover>
        {/* F-cross-13: no `asChild` — render the trigger as the button directly
            (both Radix + Base UI pass native props through to a <button>). */}
        <PopoverTrigger
          type="button"
          className={cn(buttonVariants({ variant: "outline" }), "gap-2 rounded-full")}
        >
          <CalendarIcon aria-hidden="true" className="h-4 w-4" />
          {triggerText}
          <ChevronDown aria-hidden="true" className="h-4 w-4" />
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0" align="center" dir={dir}>
          <CalendarErrorBoundary
            message={loadErrorText}
            retryText={retryText}
            onRetry={() => setDateRangeCalendar(loadCalendar)}
          >
            <Suspense fallback={<CalendarSkeleton />}>
              <DateRangeCalendar
                value={value}
                onChange={onChange}
                locale={calendarLocale}
                timeZone={timeZone}
                dir={dir}
              />
            </Suspense>
          </CalendarErrorBoundary>
        </PopoverContent>
      </Popover>

      {hasRange ? (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => onChange({ from: undefined, to: undefined })}
          aria-label={clearLabel}
          className="gap-1"
        >
          <X aria-hidden="true" className="h-3 w-3" />
          {clearText}
        </Button>
      ) : null}
    </div>
  );
}

