import type { Locale } from "react-day-picker";
import { Calendar } from "@/components/ui/calendar";
import type { DateRange } from "../types";

/**
 * The two-month range calendar. Lives in its own module so `date-range-picker.tsx` can
 * `React.lazy` it: react-day-picker + date-fns load only when the popover first opens.
 */
export function DateRangeCalendar({
  value,
  onChange,
  locale,
  timeZone,
  dir,
}: {
  value: DateRange;
  onChange: (next: DateRange) => void;
  locale?: Locale;
  timeZone?: string;
  dir: "ltr" | "rtl";
}) {
  return (
    <Calendar
      mode="range"
      defaultMonth={value.from}
      selected={value.from || value.to ? { from: value.from, to: value.to } : undefined}
      onSelect={(range) => onChange({ from: range?.from, to: range?.to })}
      numberOfMonths={2}
      locale={locale}
      timeZone={timeZone}
      dir={dir}
    />
  );
}

export default DateRangeCalendar;

"use client";

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type Direction = "ltr" | "rtl";

/**
 * Resolves text direction (consumer contract C4 / R6): the `dir` prop wins; otherwise the
 * element's direction, read after mount — the computed `direction`, or the nearest explicit
 * non-`auto` `[dir]` ancestor (jsdom has no UA stylesheet for `dir`); otherwise `"ltr"`.
 *
 * The server render and the first client render both return the prop or `"ltr"`, so markup
 * must not depend on the resolved value before mount. Key handling, swipe, carousel and
 * transition logic may. A later direction change is not observed — pass `dir` if the app
 * switches direction at runtime without remounting.
 *
 * Directional props take `"start" | "end"`; physical values stay only as deprecated aliases.
 * Copy into a component's `hooks/`. Canonical copy: `_template/_snippets/` (tests next to it).
 */
export function useDirection(
  ref: React.RefObject<HTMLElement | null>,
  dirProp?: Direction,
): Direction {
  const [resolved, setResolved] = useState<Direction>("ltr");
  useIsoLayoutEffect(() => {
    if (dirProp) return;
    const el = ref.current;
    if (!el) return;
    const explicit = el.closest('[dir]:not([dir="auto"])')?.getAttribute("dir")?.toLowerCase();
    const rtl = getComputedStyle(el).direction === "rtl" || explicit === "rtl";
    setResolved(rtl ? "rtl" : "ltr");
  }, [dirProp, ref]);
  return dirProp ?? resolved;
}

"use client";

import { Component, type ReactNode } from "react";
import { Button } from "@/components/ui/button";

/**
 * Catches a failed lazy calendar chunk so it cannot unmount the host app. The fallback
 * announces the failure (`role="alert"`) and offers a Retry that re-attempts the import.
 */
export class CalendarErrorBoundary extends Component<
  { message: string; retryText: string; onRetry: () => void; children: ReactNode },
  { failed: boolean }
> {
  override state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  private retry = () => {
    this.props.onRetry();
    this.setState({ failed: false });
  };

  override render() {
    if (!this.state.failed) return this.props.children;
    return (
      <div role="alert" className="flex flex-col items-start gap-2 p-4 text-sm">
        <span>{this.props.message}</span>
        <Button type="button" variant="outline" size="sm" onClick={this.retry}>
          {this.props.retryText}
        </Button>
      </div>
    );
  }
}
